window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d69a59d80ce8b6bf"]={"versions": [{"id": "FIG-d69a59d80ce8b6bf", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Det_Error_Reporting</code>) im Kontext der AUTOSAR Classic Platform (SWS Development Error Tracer). Das Diagramm visualisiert das Fehlermelde-Szenario über den synchronen oder asynchronen Aufruf des Development Error Tracers (<code>Det</code>) durch einen BSW- oder SW-C-Nutzer sowie die anschließende Benachrichtigung konfigurierter Fehler-Hooks in anderen BSW-Modulen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Generic Elements::User</code>: Rufende Instanz (z. B. BSW-Modul oder Software-Komponente), die einen Entwicklungsfehler feststellt.</li>\n<li><code>«module» Det::Det</code>: BSW-Modul Development Error Tracer als zentraler Empfänger der Fehlermeldung.</li>\n<li><code>other BSW module(s)</code>: Externe BSW-Module, in denen anwenderspezifische Fehlerbehandlungsroutinen (Hooks) implementiert sind.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code>: Synchrone Aufrufschnittstelle mit Modulkennung, Instanzkennung, API-Funktionskennung und Fehlercode.</li>\n<li><code>User_ErrorHook</code>: Hook-Funktionsaufruf zur Weiterleitung des Fehlers an konfigurierte Module.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die rufende Instanz <code>Generic Elements::User</code> initiiert die Fehlererfassung über den synchronen Funktionsaufruf <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> an <code>Det::Det</code>.</li>\n<li>Innerhalb eines <code>loop</code>-Interaktionsrahmens mit der Guard-Bedingung <code>[error hook list has been configured]</code> durchläuft <code>Det::Det</code> die konfigurierte Hook-Liste:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Aufruf von <code>User_ErrorHook</code> an <code>other BSW module(s)</code>.</li>\n<li>Nach Abarbeitung des Hooks erfolgt der synchrone Rücksprung zu <code>Det::Det</code>.</li>\n<li>Dieser Vorgang wird für jeden konfigurierten Hook wiederholt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Beendigung des Hooks-Durchlaufs sendet <code>Det::Det</code> den Rücksprung <code>Det_ReportError</code> an die rufende Instanz zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Ein Kommentar vermerkt explizit: „The API behavior (synchronous/asynchronous) depends on implementation“. Die SWS lässt die konkrete Ausführung der Entkopplung bzw. Pufferung der Implementierung frei.</li>\n<li>Ein weiterer Kommentar konkretisiert den Schleifenablauf: „a list of such error hooks can be configured, each hook will be called there“.</li>\n<li>Ein Metadatenfeld am unteren Bildrand dokumentiert den Entwurfsstatus: „Status: Proposed by TO as per SWS Det 1.5“.</li>\n</ul>"}, {"id": "FIG-79fd1ee816d9f7e6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext der AUTOSAR Classic Platform (SWS Development Error Tracer). Das Diagramm visualisiert das Fehlermelde-Szenario über den Aufruf des Development Error Tracers (<code>Det</code>) durch einen Nutzer sowie die Benachrichtigung konfigurierter Fehler-Hooks in anderen BSW-Modulen ohne umschließenden Sequenzrahmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>User</code>: Rufende Instanz (z. B. BSW-Modul oder SW-C).</li>\n<li><code>«module» Det</code>: BSW-Modul Development Error Tracer.</li>\n<li><code>other BSW module(s)</code>: Externe BSW-Module mit implementierten Fehler-Hooks.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code>: Aufrufschnittstelle zur Fehlerübermittlung.</li>\n<li>Hook-Rückmeldeschnittstelle im Loop-Fragment von <code>other BSW module(s)</code> an <code>Det</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Entität <code>User</code> setzt den Aufruf <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> an <code>Det</code> ab.</li>\n<li>Innerhalb eines <code>loop</code>-Interaktionsrahmens mit der Bedingung <code>[error hook list has been configured]</code> wird für konfigurierte Hooks die Interaktion mit <code>other BSW module(s)</code> ausgeführt, dargestellt über einen Ausführungsbalken an <code>other BSW module(s)</code> und eine gestrichelte Rückkehrkante zu <code>Det</code>.</li>\n<li><code>Det</code> liefert die Rückkehrnachricht <code>Det_ReportError()</code> an <code>User</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Ein Kommentar vermerkt: „The API behavior (synchronous/asynchronous) depends on implementation“.</li>\n<li>Eine Kommentar-Notiz am <code>loop</code>-Fragment erläutert: „a list of such error hooks can be configured, each hook will be called there“.</li>\n</ul>"}], "trans": [{"from": "FIG-d69a59d80ce8b6bf", "to": "FIG-79fd1ee816d9f7e6", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>UML-Rahmen: Kopfzeile <code>sd Det_Error_Reporting</code> sowie äußerer Begrenzungsrahmen entfernt.</li>\n<li>Metadaten-Notiz: Kommentarblock links unten („Status: Proposed by TO as per SWS Det 1.5“, „Description:“, „Comment:“) entfernt.</li>\n<li>Lifeline <code>Generic Elements::User</code>: Umbenannt zu <code>User</code>.</li>\n<li>Lifeline <code>Det::Det</code>: Umbenannt zu <code>Det</code>; Komponenten-Icon (zwei Ringe / Symbol unten rechts) entfernt.</li>\n<li>Aufruf <code>User_ErrorHook</code>: Die synchrone Hin-Nachricht mit Beschriftung <code>User_ErrorHook</code> fehlt im Loop-Fragment; stattdessen ist nur die gestrichelte Rückkehrnachricht von <code>other BSW module(s)</code> zu <code>Det</code> dargestellt.</li>\n<li>Rückgabenachricht: Beschriftung von <code>Det_ReportError</code> in <code>Det_ReportError()</code> geändert; Pfeil setzt nun direkt unterhalb der ersten Ausführungsphase von <code>Det</code> an.</li>\n</ul>"}]};
